// TestCLIVersionInMetadata verifies that cli_version is present in both
// the CheckpointSummary (on entire/checkpoints/v1) and the session state
// file (in .git/entire-sessions/), and that the value matches the version
// reported by the compiled binary.
func TestCLIVersionInMetadata(t *testing.T) {
	t.Parallel()
	RunForAllStrategies(t, func(t *testing.T, env *TestEnv, strategyName string) {
		// Get the expected version from the compiled binary.
		// "entire version" outputs "Entire CLI <version> (<commit>)\n..."
		versionOutput := env.RunCLI("version")
		expectedVersion := parseCLIVersion(t, versionOutput)

		// 1. Start a session and create a checkpoint
		session := env.NewSession()
		if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
			t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
		}

		// Verify cli_version in session state matches the binary's version
		state, err := env.GetSessionState(session.ID)
		if err != nil {
			t.Fatalf("GetSessionState failed: %v", err)
		}
		if state == nil {
			t.Fatal("session state should exist")
		}
		if state.CLIVersion != expectedVersion {
			t.Errorf("session state cli_version = %q, want %q", state.CLIVersion, expectedVersion)
		}

		// 2. Create a file change and checkpoint
		env.WriteFile("version-test.txt", "hello")
		session.CreateTranscript(
			"Create a test file",
			[]FileChange{{Path: "version-test.txt", Content: "hello"}},
		)
		if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
			t.Fatalf("SimulateStop failed: %v", err)
		}

		// 3. Trigger condensation by committing with hooks
		env.WriteFile("version-test.txt", "hello v2")
		env.GitCommitWithShadowHooks("Add version test file", "version-test.txt")

		// 4. Read CheckpointSummary from entire/checkpoints/v1 branch
		if !env.BranchExists(paths.MetadataBranchName) {
			t.Fatal("entire/checkpoints/v1 branch should exist after condensation")
		}

		checkpointID := env.GetLatestCheckpointID()
		summaryPath := CheckpointSummaryPath(checkpointID)
		summaryContent, found := env.ReadFileFromBranch(paths.MetadataBranchName, summaryPath)
		if !found {
			t.Fatal("root metadata.json should be readable")
		}

		var summary checkpoint.CheckpointSummary
		if err := json.Unmarshal([]byte(summaryContent), &summary); err != nil {
			t.Fatalf("failed to parse CheckpointSummary: %v", err)
		}

		// Verify CheckpointSummary cli_version matches the binary's version
		if summary.CLIVersion != expectedVersion {
			t.Errorf("CheckpointSummary cli_version = %q, want %q", summary.CLIVersion, expectedVersion)
		}
	})
}

// parseCLIVersion extracts the version string from "entire version" output.
// Expected format: "Entire CLI <version> (<commit>)\n..."
func parseCLIVersion(t *testing.T, output string) string {
	t.Helper()
	// First line: "Entire CLI dev (unknown)"
	firstLine := strings.SplitN(output, "\n", 2)[0]
	firstLine = strings.TrimPrefix(firstLine, "Entire CLI ")
	// "dev (unknown)" -> "dev"
	if idx := strings.Index(firstLine, " ("); idx >= 0 {
		return firstLine[:idx]
	}
	t.Fatalf("unexpected version output format: %q", output)
	return ""
}

